(1047, '2', '[\"577\"]', '[0]', '[\"Ketepatan mahasiswa dalam memvisualisasikan data dalam bentuk grafik, termasuk histogram, untuk mendukung interpretasi distribusi data dalam konteks analisis masalah komputasi.\"]', 'Partisipasi (Keaktifan)', '[\"Visualisasi Data: Diagram Batang, Histogram, dan Grafik Lain\"]', '{\"detail_metode\":[{\"deskripsi\":\"Pembelajaran Daring Sinkron\\/Asinkron\",\"kategori\":\"DR\",\"waktu\":\"1x(3x50\\u2019)\"}],\"pustaka\":[\"[FIT22]\"]}', '[null]', '[\"Mengikuti perkuliahan sinkronus\",\"Demo histogram\\/diagram batang\",\"Latihan interpretasi grafik\",\"Menanyakan materi yang belum jelas ke dosen\",\"Diskusi\"]', NULL, NULL, 1301, 11, '2026-02-03 08:11:39', '2026-02-03 08:11:39'),
(1048, '3', '[\"578\"]', '[0]', '[\"Ketepatan mahasiswa dalam menghitung nilai rata-rata, median, dan kuantil dari suatu himpunan data untuk mendukung analisis statistik pada permasalahan komputasi.\"]', 'Partisipasi (Keaktifan)', '[\"Ukuran Pemusatan: Rata-rata, Median, dan Kuantil\"]', '{\"detail_metode\":[{\"deskripsi\":\"Ceramah dan Latihan Terarah\",\"kategori\":\"TM\",\"waktu\":\"1x(3x50\\u2019)\"}],\"pustaka\":[\"[FIT22]\"]}', '[\"Pembahasan konsep pemusatan\",\"Latihan hitung mean\\/median\\/kuantil\",\"Diskusi kesalahan umum\"]', '[null]', NULL, NULL, 1301, 11, '2026-02-03 08:12:55', '2026-02-03 08:12:55'),
