INSERT INTO `cpls` (`id`, `aspek`, `kode`, `nomor`, `judul`, `id_kurikulum`, `id_prodi`, `created_at`, `updated_at`) VALUES
(68, 'Sikap', 'CPL-01', '01', 'Bertakwa (A5) kepada Tuhan Yang Maha Esa, taat terhadap hukum, dan disiplin (bahan kajian) dalam kehidupan bermasyarakat dan bernegara (konteks).', 1, 4, '2023-01-27 14:33:20', '2023-01-27 14:33:20'),
(69, 'Keterampilan Umum', 'CPL-02', '02', 'Menunjukkan sikap profesional melalui kepatuhan (A2) dan respon (A2) terhadap etika profesi, isu sosial serta perkembangan teknologi (bahan kajian), kemampuan bekerjasama (A3) dalam tim multidisiplin (bahan kajian), dan pemahaman (C2) tentang pembelajaran sepanjang hayat (bahan kajian).', 1, 4, '2023-01-27 14:34:43', '2023-01-27 14:34:43'),
(72, 'Keterampilan Umum', 'CPL-03', '03', 'Memiliki kemampuan memahami (C2) cara kerja sistem komputer serta menerapkan (C3) berbagai algoritma/metode (bahan kajian) untuk memecahkan masalah dalam suatu organisasi (konteks).', 1, 4, '2023-01-28 21:41:54', '2023-01-28 22:23:01'),
(73, 'Keterampilan Umum', 'CPL-04', '04', 'Memiliki kompetensi dalam menganalisis (C4) persoalan computing yang kompleks untuk mengidentifikasi solusi pengelolaan proyek teknologi di bidang informatika/ilmu komputer (bahan kajian) dengan mempertimbangkan perkembangan ilmu transdisiplin (konteks)', 1, 4, '2023-01-28 21:41:56', '2023-01-28 22:24:05'),
(74, 'Pengetahuan', 'CPL-05', '05', 'Menguasai (C2) konsep teoritis dalam bidang Informatika/Ilmu Komputer (bahan kajian) untuk mendesain dan mensimulasikan aplikasi teknologi multi-platform (bahan kajian) yang sesuai dengan kebutuhan industri dan masyarakat (konteks).', 1, 4, '2023-01-28 21:44:25', '2023-01-28 22:27:38'),
(75, 'Pengetahuan', 'CPL-06', '06', 'Memiliki kemampuan berkomunikasi (A2) dan melakukan presentasi (A2) dengan baik, baik secara lisan maupun tertulis (bahan kajian), serta mampu bekerjasama dalam tim (A3) dan mengelola (A4) kelompok maupun diri sendiri (bahan kajian) .', 1, 4, '2023-01-28 21:44:27', '2023-01-28 22:28:50'),
(76, 'Pengetahuan', 'CPL-07', '07', 'Memiliki kemampuan menyusun (C3) deskripsi saintifik dari hasil kajian implikasi pengembangan atau implementasi ilmu pengetahuan dan teknologi (bahan kajian) dalam bentuk skripsi atau laporan tugas akhir atau artikel ilmiah (konteks). ', 1, 4, '2023-01-28 21:44:27', '2023-01-28 22:32:00'),
(77, 'Keterampilan Khusus', 'CPL-08', '08', 'Memiliki kemampuan untuk mengimplementasikan (C3) kebutuhan computing dengan menggunakan berbagai metode/algoritma (bahan kajian) yang sesuai dengan kebutuhan pengguna (konteks).', 1, 4, '2023-01-28 21:46:14', '2023-01-28 22:59:43'),
(78, 'Keterampilan Khusus', 'CPL-09', '09', 'Memiliki kemampuan untuk membuat (C3), menganalisis (C4), mengevaluasi (C5) dan merancang (C6) antarmuka pengguna serta aplikasi interaktif (bahan kajian) dengan mempertimbangkan kebutuhan pengguna dan perkembangan ilmu transdisiplin (konteks).', 1, 4, '2023-01-28 21:48:42', '2023-01-28 23:00:17'),
(79, 'Keterampilan Khusus', 'CPL-10', '10', 'Memiliki kemampuan untuk mengimplementasikan (C3), mengevaluasi (C5) dan mengembangkan (C6) solusi berbasis computing multi-platform (bahan kajian) yang sesuai dengan kebutuhan computing dalam suatu organisasi (konteks).', 1, 4, '2023-01-28 21:48:44', '2023-01-28 23:00:58'),
(80, 'Keterampilan Khusus', 'CPL-11', '11', 'Having a complete knowledge and competent in applying the basic concepts of operating systems, networks and security of the system and applying it to a distributed system', 1, 4, '2023-01-28 21:48:44', '2023-01-28 23:01:54'),
(81, 'Keterampilan Khusus', 'CPL-12', '12', 'Have in-depth knowledge and competence in applying the basic concepts and principles of computer science in the fields of engineering, life sciences or social humanities', 1, 4, '2023-01-28 21:48:44', '2023-01-28 23:03:45'),
(82, 'Keterampilan Khusus', 'CPL-13', '13', 'Having a thorough understanding and capable to apply the concepts of strategy, model, and business innovation to the enterprise system.', 1, 4, '2023-01-28 21:48:44', '2023-01-28 23:04:27'),
(109, 'Keterampilan Khusus', 'CPL-01', '01', 'CPL-01 untuk D3 Manajemen Informatika Dummy Edit', 6, 3, '2025-07-10 11:01:37', '2025-07-10 11:11:32'),
(110, 'Sikap', 'CPL-02', '02', 'CPL-02 untuk D3 Manajemen Informatika Dummy', 6, 3, '2025-07-10 11:01:37', '2025-07-10 11:01:37'),
(111, 'Keterampilan Khusus', 'CPL-05', '05', 'CPL-03 untuk D3 Manajemen Informatika', 6, 3, '2025-07-10 11:18:13', '2025-07-10 11:18:45'),
(112, 'Keterampilan Khusus', 'CPL-04', '04', 'CPL-04 untuk D3 Manajemen Informatika', 6, 3, '2025-07-10 11:18:13', '2025-07-10 11:18:13'),
(117, 'Sikap', 'CPL01', '01', 'Bertakwa kepada Tuhan Yang Maha Esa dan menjunjung tinggi nilai-nilai agama, moral, etika, taat hukum dan memiliki nasionalisme dan tanggung jawab untuk berkontribusi pada bangsa dan negara.', 13, 12, '2025-07-15 10:46:25', '2025-07-15 11:18:20'),
(118, 'Sikap', 'CPL02', '02', 'Mampu menjelaskan, menerapkan dan menganalisis prinsip-prinsip, teori, dan metode dalam ilmu komputer yang menjadi dasar dalam pengembangan sistem berbasis komputer yang berkualitas pada berbagai bidang terapan. Prinsip-prinsip tersebut adalah metode kuantitatif dan analisis algoritma serta salah satu dari prinsip berikut 1) rekayasa sistem perangkat lunak atau, 2) sistem jaringan komputer dan komunikasi data atau, 3) pembelajaran mesin', 13, 12, '2025-07-15 10:46:25', '2025-07-15 11:18:29'),
(119, 'Sikap', 'CPL03', '03', 'Mampu merancang dan menghasilkan alternatif solusi berbasis komputer, baik teknologi maupun metodologi dari salah satu bidang berikut: sains data, kecerdasan buatan, sistem informasi, bioinformatika,  sistem terdistribusi, rekayasa perangkat lunak, dan ilmu informasi untuk memecahkan permasalahan nyata pada berbagai bidang terapan.', 13, 12, '2025-07-15 10:46:25', '2025-07-15 11:18:35'),
(120, 'Sikap', 'CPL04', '04', 'Mampu mengelola proyek penelitian teknologi informasi dan komputer multidisiplin dengan memperhatikan dan mematuhi prinsip-prinsip legal dan etika komputasi di bidang ilmu komputer dan mendiseminasikan hasil penelitiannya pada publikasi ilmiah yang mendapat pengakuan nasional atau internasional.', 13, 12, '2025-07-15 10:46:25', '2025-07-15 11:18:41'),
(121, 'Sikap', 'CPL05', '05', 'Mampu bekerjasama dan mengkomunikasikan ide dan pendapat secara logis dan sistematis  dalam tim untuk menyelesaikan suatu proyek atau riset ilmiah.', 13, 12, '2025-07-15 10:46:25', '2025-07-15 11:18:50'),
(122, 'Sikap', 'CPL01', '01', 'Ini CPL Dummy Milik S2 Ilkomp Dumy', 15, 7, '2026-01-14 10:49:20', '2026-01-14 10:49:20'),
(123, 'Keterampilan Umum', 'CPL02', '02', 'Ini CPL Dummy Milik S2 Ilkomp Dumy Versi 2', 15, 7, '2026-01-14 16:09:12', '2026-01-14 16:09:12'),
(131, 'Sikap', 'CPL01', '01', 'Ini CPL Dummy s2', 16, 7, '2026-01-14 16:56:23', '2026-01-14 16:56:23'),
(136, 'Sikap', 'CPL01', '01', 'Memiliki sikap religius, toleransi terhadap perbedaan, tanggung jawab sosial, serta menjunjung tinggi hukum, etika profesi, dan norma kehidupan bermasyarakat dan pelestarian lingkungan.', 14, 11, '2026-01-27 20:23:10', '2026-01-27 20:23:10'),
(137, 'Keterampilan Umum', 'CPL02', '02', 'Mampu berpikir logis, kritis, sistematis, dan inovatif dalam menyelesaikan masalah menggunakan pendekatan ilmiah serta menerapkan ilmu humaniora untuk mendukung pengambilan keputusan berbasis informasi dan data.', 14, 11, '2026-01-27 20:23:39', '2026-01-27 20:23:39'),
(138, 'Pengetahuan', 'CPL03', '03', 'Menguasai konsep dasar matematika, statistika, algoritma, dan pemrograman, serta mampu menggunakannya dalam analisis dan penyelesaian masalah komputasi dan sistem cerdas.', 14, 11, '2026-01-27 20:23:39', '2026-01-27 20:23:39'),
(139, 'Keterampilan Khusus', 'CPL04', '04', 'Menguasai prinsip rekayasa perangkat lunak, manajemen proyek perangkat lunak, serta mampu merancang, membangun, dan mengevaluasi sistem berbasis kebutuhan pengguna.', 14, 11, '2026-01-27 20:35:29', '2026-01-27 20:35:29'),
(141, 'Pengetahuan & Keterampilan', 'CPL05', '05', 'Mampu menerapkan konsep teknologi digital, organisasi komputer, sistem operasi, jaringan, dan keamanan sistem termasuk dalam sistem terdistribusi, cloud dan big data.', 14, 11, '2026-01-27 20:49:45', '2026-01-27 20:55:24'),
(142, 'Pengetahuan Interdisipliner', 'CPL06', '06', 'Mampu menerapkan ilmu komputer dalam bidang interdisipliner (rekayasa, hayati, sosial) serta mengembangkan inovasi berbasis strategi dan model bisnis dalam sistem enterprise.', 14, 11, '2026-01-27 20:56:19', '2026-01-27 20:56:19'),
(143, 'Keterampilan Umum & Khusus', 'CPL07', '07', 'Mampu berkomunikasi efektif secara lisan dan tulisan, bekerja dalam tim lintas disiplin, serta memiliki jiwa kewirausahaan dalam pengembangan solusi teknologi.', 14, 11, '2026-01-27 20:56:19', '2026-01-27 20:56:19'),
(144, 'Sikap', 'CPL01', '01', 'Lulusan mampu menunjukkan kepribadian yang berakhlak dan  berintegritas melalui proses pembelajaran yang menghargai  kebhinekaan Indonesia dan nilai-nilai budaya daerah.', 17, 9, '2026-06-08 17:28:20', '2026-06-08 17:28:20'),
(145, 'Keterampilan Umum', 'CPL02', '02', 'Lulusan mampu menunjukkan keterampilan Lulusan mampu menunjukkan keterampilan menggunakan konsep,  teori, dan metode secara logis, kritis, sistematis, dan inovatif melalui  proses pembelajaran yang menekankan etika akademis ilmiah. menggunakan konsep,  teori, dan metode secara logis, kritis, sistematis, dan inovatif melalui  proses pembelajaran yang menekankan etika akademis ilmiah.', 17, 9, '2026-06-08 17:28:20', '2026-06-08 20:18:02'),
(146, 'Pengetahuan & Keterampilan', 'CPL03', '03', 'Lulusan mampu menunjukkan keterampilan menggunakan konsep  dan teori Bahasa Inggris melalui proses pembelajaran ilmu  kebahasaan, kesusastraan, dan pedagogi secara kritis dan reflektif', 17, 9, '2026-06-08 17:28:20', '2026-06-08 17:28:20'),
(147, 'Keterampilan Khusus', 'CPL04', '04', 'Lulusan mampu menunjukkan keterampilan menggunakan konsep,  teori, dan metode yang inovatif melalui proses pembelajaran Bahasa  Inggris berbasis TPACK (Technological Pedagogical Content  Knowledge) terkait dengan pemahaman peserta didik dan  pembelajaran yang mendidik.', 17, 9, '2026-06-08 17:28:20', '2026-06-08 17:28:20'),
(148, 'Keterampilan Khusus', 'CPL05', '05', 'Lulusan mampu menunjukkan keterampilan menggunakan konsep,  teori, dan metode yang inovatif melalui proses pembelajaran bidang  kewirausahaan  (edutechnopreneur)', 17, 9, '2026-06-08 17:28:20', '2026-06-08 17:28:20'),
(149, 'Sikap', 'CPL01', '01', 'Lulusan mampu menunjukkan kepribadian yang berakhlak dan  berintegritas melalui proses pembelajaran yang menghargai  kebhinekaan Indonesia dan nilai-nilai budaya daerah.', 18, 17, '2026-06-14 20:49:06', '2026-06-14 20:49:06'),
(150, 'Keterampilan Umum', 'CPL02', '02', 'Lulusan mampu menunjukkan keterampilan menggunakan konsep,  teori, dan metode secara logis, kritis, sistematis, dan inovatif melalui  proses pembelajaran yang menekankan etika akademis ilmiah.', 18, 17, '2026-06-14 20:58:28', '2026-06-14 20:58:28'),
(151, 'Pengetahuan', 'CPL03', '03', 'Lulusan mampu menunjukkan keterampilan menggunakan konsep  dan teori Bahasa Inggris melalui proses pembelajaran ilmu  kebahasaan, kesusastraan, dan pedagogi secara kritis dan reflektif', 18, 17, '2026-06-14 20:58:28', '2026-06-14 20:58:28'),
(152, 'Keterampilan Khusus', 'CPL04', '04', 'Lulusan mampu menunjukkan keterampilan menggunakan konsep,  teori, dan metode yang inovatif melalui proses pembelajaran Bahasa  Inggris berbasis TPACK (Technological Pedagogical Content  Knowledge) terkait dengan pemahaman peserta didik dan  pembelajaran yang mendidik.', 18, 17, '2026-06-14 20:58:28', '2026-06-14 20:58:28'),
(153, 'Sikap', 'CPL7777', '7777', 'tes p', 19, 17, '2026-06-15 16:44:55', '2026-06-15 16:44:55'),
(155, 'Sikap', 'CPL1', '1', 'Bertakwa kepada Tuhan Yang Maha Esa, menjunjung tinggi nilai kemanusiaan, etika akademik, dan profesionalisme dalam bidang Pendidikan IPA.', 20, 20, '2026-07-22 18:12:44', '2026-07-22 18:12:44');
