INSERT INTO `profil_lulusan` (`id`, `namaProfil`, `kode`, `deskripsi`, `jenis`, `status`, `acuan`, `id_prodi`, `kurikulum_id`) VALUES
(1, 'Programming and Software Development', 'PL01', 'Lulusan memiliki kemampuan menganalisis persoalan computing serta menerapkan prinsip- prinsip computing dan disiplin ilmu relevan lainnya untuk mengidentifikasi solusi bagi organisasi.  (Software Engineer, Analis Program, Web Developer)', 'Keterampilan Umum', 'wajib', 'Sn Dikti', 4, 1),
(2, 'IT Mobility and Internet of Things', 'PL02', 'Lulusan mampu berpikir logis, kritis serta sistematis dalam memanfaatkan ilmu\npengetahuan informatika/ilmu komputer untuk menyelesaikan masalah nyata. (Cloud Computing Developer, Advance Mobile Computing)', 'Keterampilan Umum', 'wajib', 'IABEE', 4, 1),
(3, 'Instruktur and Asisten Peneliti ', 'PL03', 'Lulusan mampu bertindak dan menilai secara profesional dibidang Informatika/Ilmu Komputer.', 'Pengetahuan', 'wajib', 'IABEE', 4, 1),
(4, 'Artificial Intelligence', 'PL04', 'Lulusan memiliki kemampuan menganalisis, merancang, dan mengimplementasikan perangkat lunak serta solusi berbasis komputasi, termasuk kecerdasan buatan, yang sesuai dengan kebutuhan pengguna.  (AI Engineer)', 'Keterampilan Khusus', 'wajib', 'SN dikti', 4, 1),
(43, '', 'PL01', 'Lulusan yang memiliki kemampuan untuk mengembangkan pengetahuan di bidang ilmu komputer melalui penelitian yang sistematis, orisinal, dan berbasis metodologi ilmiah. Mereka mampu merancang dan melaksanakan penelitian di bidang komputasi, mempublikasikan hasilnya di forum ilmiah, serta berkontribusi dalam pengembangan ilmu pengetahuan dan pendidikan tinggi. Lulusan ini juga mampu mengintegrasikan hasil riset ke dalam proses pembelajaran dan inovasi teknologi secara berkelanjutan.', 'Umum', 'wajib', 'fakultas', 12, 13),
(44, '', 'PL02', 'Memiliki kompetensi mendalam dalam menganalisis permasalahan, merancang, dan mengimplementasikan solusi teknologi informasi di bidang ilmu komputer yang inovatif dan efisien untuk mendukung kebutuhan organisasi. Mereka mampu memberikan rekomendasi strategis berbasis riset dan praktik terbaik, serta memimpin proses transformasi digital dengan mempertimbangkan aspek teknis, bisnis, dan keamanan. Lulusan ini juga mampu berperan sebagai penghubung antara tim teknis dan manajemen dalam pengambilan keputusan berbasis TI.', 'Sikap', 'wajib', 'Fakultas', 12, 13),
(45, '', 'PL03', 'Mampu merancang, mengembangkan, dan mengimplementasikan solusi berbasis teknologi informasi yang inovatif untuk menjawab tantangan di berbagai sektor. Dengan bekal keahlian komputasi lanjutan dan pemikiran kritis, lulusan ini mampu menciptakan produk, sistem, atau layanan digital yang adaptif, efisien, dan berdampak, serta mendorong transformasi digital yang berkelanjutan dalam masyarakat dan industri.', 'Sikap', 'wajib', 'Fakultas', 12, 13),
(53, '', 'PL01', 'Lulusan memiliki sikap Berintegritas dan CREATIVE (Collaborative, REsponsive, Analytics, Transformative, Impactful, Visionary, and Excellency)', 'Sikap', 'wajib', 'Fakultas', 11, 14),
(54, '', 'PL02', 'Lulusan mampu berpikir logis, kritis serta sistematis dalam memanfaatkan ilmu pengetahuan informatika/ ilmu komputer untuk menyelesaikan masalah nyata.', 'Pengetahuan', 'wajib', 'KKNI', 11, 14),
(55, '', 'PL03', 'Lulusan memiliki kemampuan menganalisis persoalan computing serta menerapkan prinsip-prinsip computing dan disiplin ilmu relevan lainnya untuk mengidentifikasi solusi bagi organisasi.', 'Pengetahuan', 'wajib', 'IABEE', 11, 14),
(56, '', 'PL04', 'Lulusan memiliki kemampuan mendesain, mengimplementasi dan mengevaluasi solusi berbasis computing termasuk kecerdasan buatan yang memenuhi kebutuhan pengguna dengan pendekatan yang sesuai.', 'Keterampilan Khusus', 'wajib', 'IABEE', 11, 14),
(69, 'Pendidik', 'PL01', 'Sarjana pendidikan yang memiliki kemampuan kerja,\npenguasaan pengetahuan, kemampuan manajerial, kemampuan meneliti, tanggung jawab sebagai pendidik dalam bidang matapelajaran Bahasa Inggris pada jenjang pendidikan menengah dan menengah atas, baik jalur pendidikan formal maupun non-formal, yang berkepribadian baik, transformatif, berpengetahuan luas dan inovatif di bidangnya serta mampu mengembangkan keprofesiannya secara berkelanjutan dengan menjadi pembelajar sepanjang hayat.', '', 'wajib', '', 9, 17),
(70, 'Wirausahawan (Edutechnopreuneur)', 'PL02', 'Sarjana pendidikan yang memiliki kemampuan kerja, penguasaan pengetahuan, kemampuan manajerial, tanggung jawab sebagai wirausahawan di bidang pendidikan Bahasa Inggris yang menguasai dan mampu menerapkan prinsip-prinsip pengembangan program, mampu merancang, melaksanakan, mengevaluasi, dan meningkatkan secara berkelanjutan.', '', 'wajib', '', 9, 17),
(73, 'Pengajar', 'PL01', 'Sarjana pendidikan yang memiliki kemampuan kerja, \npenguasaan pengetahuan, kemampuan manajerial, kemampuan meneliti, tanggung jawab sebagai pendidik dalam bidang matapelajaran Bahasa Inggris pada jenjang pendidikan menengah dan menengah atas, baik jalur pendidikan formal maupun non-formal, yang berkepribadian baik, transformatif, berpengetahuan luas dan inovatif di bidangnya serta mampu mengembangkan keprofesiannya secara berkelanjutan dengan menjadi pembelajar sepanjang hayat.', '', 'wajib', '', 17, 18),
(74, 'Wirausahawan', 'PL02', 'Sarjana pendidikan yang memiliki kemampuan kerja, penguasaan pengetahuan, kemampuan manajerial, tanggung jawab sebagai wirausahawan di bidang pendidikan Bahasa Inggris yang menguasai dan mampu menerapkan prinsip-prinsip pengembangan program, mampu merancang, melaksanakan, mengevaluasi, dan meningkatkan secara berkelanjutan.', '', 'wajib', '', 17, 18),
(76, 'Pendidik IPA Profesional', 'PL01', 'Lulusan mampu merancang, melaksanakan, dan mengevaluasi pembelajaran IPA pada jenjang pendidikan menengah maupun perguruan tinggi dengan memanfaatkan teknologi, inovasi pembelajaran, serta menjunjung tinggi etika profesi.', '', 'wajib', '', 20, 20);
